using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed partial class UnitDirectiveCancelRetryTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:unit-recipient/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(Input(s,action) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Away(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Query(WorldSession s,int unit)=>Input(s,NewMilitaryAction.InquireUnitKnown) with{InquiryTarget=new(NewGameMilitary.UnitRecipientContract,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[unit])!),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 static TroopDispatch Dispatch(WorldSession s,int unit){var i=Query(s,unit);var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();}
 static UnitPostInquiryAnswer Answer(ContractWorld w,TroopReceipt receipt)=>ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));

 static NewMilitaryInput Directive(WorldSession s,int unit,UnitDirectiveKind kind){var w=s.DiagnosticSnapshot();var k=NewGameMilitary.SelectKnownTarget(w,NewGameMilitary.UnitIds[unit])!;return Input(s,NewMilitaryAction.SendUnitDirective) with{Directive=new(NewGameMilitary.UnitDirectiveContract,k,kind,kind==UnitDirectiveKind.Move?new(k.Position.X+8000,k.Position.Y):null),DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract,OriginalPolicy=NewGameMilitary.UnitDirectiveHoldingContract};}

 static TroopDispatch FailedOriginal(WorldSession s,bool learn=true,int index=1,UnitDirectiveKind kind=UnitDirectiveKind.Move,bool holding=true){Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,index,kind) with{OriginalPolicy=holding?NewGameMilitary.UnitDirectiveHoldingContract:null};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,root.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(r.Delivered);if(learn)At(s,r.ReplyDueAt);return root;}
 static void HomeUnits(WorldSession s){long end=s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,Math.Max(s.Seconds,end+2));}
 static NewMilitaryInput Retry(WorldSession s,TroopDispatch root)=>Input(s,NewMilitaryAction.RetryUnitDirective) with{DirectiveRetry=new(NewGameMilitary.UnitDirectiveRetryContract,root.Id,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};

 static UnitHeldTransfer Handoff(WorldSession s,TroopDispatch root){var paper=NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id);Assert.NotNull(paper);var input=Input(s,NewMilitaryAction.DeliverHeldUnitDirective) with{DirectiveHandoff=paper};var result=s.DecideNewMilitary(input,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();}
 static TroopDispatch Cancel(WorldSession s,TroopDispatch root,long? effective=null){var w=s.DiagnosticSnapshot();var p=new UnitDirectiveCancellationInput(NewGameMilitary.UnitDirectiveCancellationContract,root.Id,NewGameMilitary.SelectKnownTarget(w,root.Recipient)!,effective??s.Seconds);var i=Input(s,NewMilitaryAction.CancelUnitDirective) with{DirectiveCancellation=p,DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};var result=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();}
 static TroopDispatch MissedCancel(WorldSession s,bool learn=true){Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var command=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();var d=Cancel(s,command);At(s,d.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single();Assert.False(r.Delivered);if(learn)At(s,r.ReplyDueAt);return d;}
 static NewMilitaryInput RetryCancel(WorldSession s,TroopDispatch root)=>Input(s,NewMilitaryAction.RetryUnitDirectiveCancellation) with{DirectiveCancelRetry=new(NewGameMilitary.UnitDirectiveCancelRetryContract,root.Id,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 [Fact]public void PhysicallyKnownFailureRetriesSameCancellationOnceAndRestoresSameFuture(){var s=Away();var root=MissedCancel(s);HomeUnits(s);var before=s.DiagnosticSnapshot();var initial=before.NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single();var envelope=before.Messaging.Messages.Single(m=>m.Id==root.Message);Assert.True(NewGameMilitary.UnitDirectiveCancelRetryAllowed(before,root.Id));var i=RetryCancel(s,root);var result=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();Assert.Equal(root.Message,copy.Message);Assert.NotEqual(root.Id,copy.Id);Assert.Equal(envelope,s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==copy.Message));Assert.Contains("取消を再送",NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),root.Id));At(s,copy.DueAt-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,copy.DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.CanonicalHash(initial),ContractJson.CanonicalHash(w.NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single(r=>r.Id==root.Id)));Assert.Single(w.NewMilitary.UnitDirective.Cancellation.Effects);Assert.Equal(root.Id,w.NewMilitary.UnitDirective.Cancellation.Effects.Single().Id);Assert.Equal(UnitCancelDisposition.Suppressed,w.NewMilitary.UnitDirective.Cancellation.Effects.Single().Outcome);var receipt=w.NewMilitary.UnitDirective.Cancellation.Receipts.Single(r=>r.Id==copy.Id);Assert.True(receipt.Delivered);Assert.False(NewGameMilitary.ReceiptConfirmedToSender(w,root.Message,w.PlayerControl.Value));foreach(var v in new[]{s,restored})At(v,receipt.ReplyDueAt);w=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.ReceiptConfirmedToSender(w,root.Message,w.PlayerControl.Value));Assert.False(NewGameMilitary.UnitDirectiveCancelRetryAllowed(w,root.Id));Assert.Contains("未実行の対象原本を取消",NewGameMilitary.UnitDirectiveCancellationOriginalStatus(w,root.Id));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(w);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]public void InvalidCancellationRetryIsAtomic(int variant){var s=Away();var root=MissedCancel(s);var i=RetryCancel(s,root);var p=i.DirectiveCancelRetry!;i=variant switch{0=>i with{DirectiveCancelRetry=p with{Contract="unknown"}},1=>i with{DirectiveCancelRetry=p with{Cancellation=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.First().Id}},2=>i with{DirectiveCancelRetry=p with{Known=p.Known with{Unit=NewGameMilitary.UnitIds[2]}}},3=>i with{DirectiveCancelRetry=p with{Known=p.Known with{Position=new(p.Known.Position.X+1,p.Known.Position.Y)}}},4=>i with{Amount=1},5=>i with{DeliverBy=s.Seconds+600},6=>i with{DirectiveCancelRetry=null},_=>i with{TransportPolicy=null}};string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void PhysicalFailureMustReturnBeforeRetryAndOldSaveOmitsRetry(){var s=Away();var root=MissedCancel(s,false);var w=s.DiagnosticSnapshot();Assert.False(MessageFlow.FailureKnown(w.Messaging,root.Attempt,w.PlayerControl.Value));Assert.False(NewGameMilitary.UnitDirectiveCancelRetryAllowed(w,root.Id));string before=ContractJson.CanonicalHash(w);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(RetryCancel(s,root),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Assert.DoesNotContain("DirectiveCancelRetry",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));At(s,w.NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single().ReplyDueAt);Assert.True(NewGameMilitary.UnitDirectiveCancelRetryAllowed(s.DiagnosticSnapshot(),root.Id));new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void DuplicateRetryRequestCannotCreateAnotherAttemptOrEffect(){var s=Away();var root=MissedCancel(s);var i=RetryCancel(s,root);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));At(s,copy.DueAt);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Equal(2,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==root.Message));new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void OriginalReceiptDeadlineCannotBeExtendedByRetry(){var s=Away();var root=MissedCancel(s);long until=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==root.Message).DeliverBy!.Value;At(s,until);Assert.False(NewGameMilitary.UnitDirectiveCancelRetryAllowed(s.DiagnosticSnapshot(),root.Id));string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(RetryCancel(s,root),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 static void MoveRetryPerson(WorldSession s,FieldPoint p){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=p},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);}
 [Fact]public void FutureRequestedTimeAndActualCopyReturnAddressSurviveRestore(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var command=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();long requested=s.Seconds+500;var root=Cancel(s,command,requested);At(s,root.DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single().ReplyDueAt);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());MoveRetryPerson(s,new(a.X-20000,a.Y));var input=RetryCancel(s,root);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();At(s,copy.DueAt);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single(r=>r.Id==copy.Id).ReplyDueAt);Assert.Contains("効力時刻を待つ",NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),root.Id));At(s,requested-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,requested);var w=s.DiagnosticSnapshot();Assert.Equal(root.Id,w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().Id);Assert.Equal(requested,w.NewMilitary.UnitDirective.Cancellation.Effects.Single().At);var notice=w.NewMilitary.UnitDirective.Cancellation.Notices.Single();Assert.Equal(copy.Origin,notice.Destination);Assert.NotEqual(root.Origin,notice.Destination);foreach(var v in new[]{s,restored})At(v,notice.DueAt);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void ThreeRealMissedAttemptsExhaustOriginalWithoutCreatingRetainedPaper(){var s=Away();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());MoveRetryPerson(s,new(a.X-90000,a.Y));var root=MissedCancel(s);var envelope=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==root.Message);for(int n=2;n<=3;n++){Assert.True(NewGameMilitary.UnitDirectiveCancelRetryAllowed(s.DiagnosticSnapshot(),root.Id));Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(RetryCancel(s,root),s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();At(s,copy.DueAt);var miss=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single(r=>r.Id==copy.Id);Assert.False(miss.Delivered);At(s,miss.ReplyDueAt);Assert.Equal(n,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,root.Message).Number);}var w=s.DiagnosticSnapshot();Assert.False(NewGameMilitary.UnitDirectiveCancelRetryAllowed(w,root.Id));Assert.Equal(envelope,w.Messaging.Messages.Single(m=>m.Id==root.Message));Assert.Empty(w.NewMilitary!.UnitDirective!.Cancellation!.Effects);Assert.DoesNotContain(NewGameMilitary.HeldPapers(w,s.Seconds),h=>h.Message==root.Message);new WorldSession(w);}
 [Fact]public void RewritingRootNoteToCopiedRequestIsRejectedOnLoad(){var s=Away();var root=MissedCancel(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(RetryCancel(s,root),s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();var copy=w.NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();int n=Array.FindIndex(w.Messaging.Messages,m=>m.Id==root.Message);var m=w.Messaging.Messages[n];var note=ContractJson.Read<UnitDirectiveCancellationNote>(System.Text.Encoding.UTF8.GetBytes(m.Body));w.Messaging.Messages[n]=m with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(note with{Request=copy.Id}))};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void UnseenFormalReceiptDoesNotChangeSenderRetryAvailabilityOrStatus(){var s=Away();var root=MissedCancel(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(RetryCancel(s,root),s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();var before=NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),root.Id);Assert.False(NewGameMilitary.UnitDirectiveCancelRetryAllowed(s.DiagnosticSnapshot(),root.Id));At(s,copy.DueAt);var w=s.DiagnosticSnapshot();Assert.Contains(w.Messaging.Receipts,r=>r.MessageId==root.Message);Assert.False(NewGameMilitary.ReceiptConfirmedToSender(w,root.Message,w.PlayerControl.Value));Assert.Equal(before,NewGameMilitary.UnitDirectiveCancellationOriginalStatus(w,root.Id));Assert.False(NewGameMilitary.UnitDirectiveCancelRetryAllowed(w,root.Id));new WorldSession(w);}
}
